import json, random, sys
sys.path.insert(0,'.')
from h2 import *
random.seed(777)
# Generate mostly-valid requests, then verify fixed-point: re-submitting an
# accepted wire yields the same decision (for the safe cases).
USER = ['a','al','b','c','zz','A','%61']
HOST = ['x.test','X.TEST','y.test.','z.test','127.0.0.1']
def rnd_from():
    style = random.random()
    uri = random.choice(['sip:a@x.test','sip:al@x.test','tel:+15550001','sip:b@y.test',
                         'sip:anonymous@anonymous.invalid','sip:zz@x.test','sip:c@z.test'])
    if random.random() < 0.5:
        uri = uri.upper().replace('SIP:','sip:')
    if style < 0.4:
        return '<%s>' % uri
    if style < 0.6:
        return uri
    if style < 0.8:
        return '"Qu, ote\\" x" <%s>' % uri
    return 'Bob Smith <%s>' % uri
def rnd_addr(allow_tag):
    s = rnd_from()
    if allow_tag and random.random() < 0.5:
        s += random.choice([';tag=t1', ' ; tag = t1 ', ';tag=' + 'x'*130, ';foo=t1'])
    return s
def rnd_claim():
    a = rnd_addr(False)
    if random.random() < 0.3:
        b = rnd_addr(False)
        a = a + ' , ' + b
    return a
def good_request():
    body = random.choice(['hi', '', 'x'*30, 'a\r\nb'])
    hdrs = ['From: ' + rnd_from() + random.choice([';tag=t1','',' ;tag=t1']),
            'To: ' + rnd_addr(False),
            'Call-ID: ' + random.choice(['c1','A.b_1@x','c'*128]),
            'CSeq: ' + random.choice(['1 MESSAGE','0009 MESSAGE','7 INVITE']) + random.choice(['','\t']),
            'Content-Length: %d' % len(body)]
    for name, prob in (('P-Asserted-Identity', .4), ('P-Preferred-Identity', .3),
                       ('Remote-Party-ID', .2), ('Privacy', .3), ('Content-Type', .4), ('Authorization', .3)):
        if random.random() < prob:
            if name == 'Privacy':
                v = random.choice(['id','none','ID','bogus'])
            elif name == 'Content-Type':
                v = random.choice(['text/plain','application/sdp;a=b'])
            elif name == 'P-Asserted-Identity':
                v = rnd_claim()
            else:
                v = rnd_addr(False)
            hdrs.append('%s: %s' % (name, v))
    random.shuffle(hdrs)
    lines = ['MESSAGE %s SIP/2.0' % random.choice(['sip:b@y.test','sip:B@Y.TEST.','sip:anonymous@anonymous.invalid'])] + hdrs
    return '\r\n'.join(lines) + '\r\n\r\n' + body

mismatch = 0
checked = 0
for trial in range(1500):
    jobs = []
    kind = random.choice(['local','peer'])
    gw = random.choice(['edge','far','any'])
    for k in range(2):
        if kind == 'local':
            ing = {'kind':'local','subject':random.choice(['s1','s2','ghost'])}
        else:
            ing = {'kind':'peer','name':'edge'}
        jobs.append({'gateway': gw, 'ingress': ing, 'trusted_out': True,
                     'raw' if k == 0 else 'source': good_request() if k == 0 else 0})
    res = run(batch(jobs))['results']
    r0 = res[0]
    if r0['status'] == 'accept':
        wire = r0['wire']
        # re-submit identical context
        if kind == 'local' and not r0['private']:
            jobs2 = [{'gateway': gw, 'ingress': {'kind':'local','subject':'s1'}, 'trusted_out': True, 'raw': wire}]
            exp = {'identity': r0['identity'], 'basis':'local', 'private': False}
            checked += 1
        elif kind == 'peer' and 'P-Asserted-Identity' in wire:
            jobs2 = [{'gateway': gw, 'ingress': {'kind':'peer','name':'edge'}, 'trusted_out': True, 'raw': wire}]
            exp = {'identity': r0['identity'], 'basis':'peer', 'private': r0['private']}
            checked += 1
        else:
            continue
        r1 = run(batch(jobs2))['results'][0]
        if r1['status'] != 'accept' or any(r1.get(k) != v for k, v in exp.items()) or r1['wire'] != wire:
            mismatch += 1
            print('MISMATCH', json.dumps({'wire': wire, 'first': r0, 'second': r1})[:400])
            if mismatch > 3: break
print('checked', checked, 'mismatch', mismatch)
